import{z,d as f,y as j,c as i,a,t,F as v,j as c,u as y,p as P,w,g as A,k as h,h as D,o as s,e as R,_ as S}from"./index-BVD8TOyU.js";const O={terms:{title:"Obchodné podmienky",perex:"Tieto obchodné podmienky upravujú práva a povinnosti pri používaní portálu {site}. Znenie je účinné od {effectiveFrom} (verzia {version}).",sections:[{heading:"Čl. 1 — Prevádzkovateľ",paragraphs:["1.1 Prevádzkovateľom portálu {site} (ďalej len „Portál“) je {name}, so sídlom {address}, IČO: {ico}, {dic}, {registration} (ďalej len „Prevádzkovateľ“).","1.2 Kontaktné údaje: e-mail {email}, telefón {phone}.","1.3 Orgánom dozoru je Slovenská obchodná inšpekcia — {soi}."]},{heading:"Čl. 2 — Vymedzenie pojmov",paragraphs:["2.1 Portál — webová aplikácia dostupná na adrese {site}, ktorá zverejňuje informácie o kultúrnych, spoločenských, športových a iných podujatiach a súvisiace služby.","2.2 Používateľ — fyzická alebo právnická osoba, ktorá Portál používa, aj bez registrácie.","2.3 Registrovaný používateľ — Používateľ, ktorý má na Portáli vytvorený účet.","2.4 Organizátor — Registrovaný používateľ, ktorý na Portáli zverejňuje podujatia, prípadne cez Portál ponúka vstupenky.","2.5 Návštevník — Používateľ, ktorý si cez Portál rezervuje alebo kúpi vstupenku, prípadne sa prihlási na podujatie.","2.6 Obsah — texty, fotografie, plagáty, odkazy a ďalšie údaje, ktoré na Portál vloží Používateľ.","2.7 Zmluva — zmluva o poskytovaní služieb Portálu medzi Prevádzkovateľom a Registrovaným používateľom, ktorej obsahom sú tieto podmienky."]},{heading:"Čl. 3 — Registrácia a používateľský účet",paragraphs:["3.1 Registrácia je bezplatná a dobrovoľná. Prehliadanie zverejnených podujatí je možné aj bez nej.","3.2 Účet si môže vytvoriť osoba staršia ako 16 rokov. Za mladšiu osobu môže konať iba jej zákonný zástupca.","3.3 Registráciu Používateľ dokončí vyplnením formulára a zaškrtnutím súhlasu s týmito podmienkami. Zmluva vzniká overením e-mailovej adresy, prípadne prvým prihlásením cez účet Google alebo Facebook.","3.4 Používateľ uvádza pravdivé a aktuálne údaje a zodpovedá za utajenie prístupových údajov k účtu. Podozrenie na zneužitie účtu bezodkladne oznámi na {email}.","3.5 Účet je neprenosný. Používateľ zodpovedá za konanie, ku ktorému došlo prostredníctvom jeho účtu.","3.6 Ak sa Používateľ registruje ako Organizátor v mene právnickej osoby, vyhlasuje, že je oprávnený za ňu konať."]},{heading:"Čl. 4 — Obsah zverejňovaný Používateľom",paragraphs:["4.1 Za správnosť, zákonnosť a aktuálnosť Obsahu zodpovedá Používateľ, ktorý ho vložil. Prevádzkovateľ Obsah nevytvára a neručí za jeho úplnosť ani pravdivosť.","4.2 Vložením Obsahu udeľuje Používateľ Prevádzkovateľovi bezodplatnú, nevýhradnú a územne neobmedzenú licenciu na jeho zobrazovanie, rozmnožovanie, úpravu veľkosti a šírenie v rozsahu potrebnom na prevádzku a propagáciu Portálu vrátane náhľadov vo vyhľadávačoch a na sociálnych sieťach, a to na čas zverejnenia Obsahu na Portáli.","4.3 Používateľ vyhlasuje, že je oprávnený takúto licenciu udeliť a že Obsah neporušuje práva tretích osôb, najmä autorské práva, práva na ochranu osobnosti a práva k ochranným známkam.","4.4 Zakázaný je Obsah, ktorý je v rozpore s právnym poriadkom Slovenskej republiky alebo s dobrými mravmi, najmä nenávistný, hanlivý, klamlivý, zásadne nesúvisiaci s podujatiami, propagujúci násilie alebo nevhodný pre maloletých.","4.5 Prevádzkovateľ je oprávnený Obsah, ktorý porušuje tieto podmienky, nezverejniť, upraviť jeho zaradenie do kategórií alebo ho odstrániť. O odstránení Používateľa informuje; Používateľ môže proti tomu podať námietku na {email}.","4.6 Prevádzkovateľ nie je povinný Obsah vopred kontrolovať. Na oznámenie o protiprávnom Obsahu doručené na {email} reaguje bez zbytočného odkladu."]},{heading:"Čl. 5 — Vstupenky a platby",paragraphs:["5.1 Ak Portál umožňuje rezerváciu alebo predaj vstupeniek, Prevádzkovateľ koná ako sprostredkovateľ v mene a na účet Organizátora. Zmluva o účasti na podujatí vzniká medzi Návštevníkom a Organizátorom, nie s Prevádzkovateľom.","5.2 Cena vstupenky je uvedená vrátane dane z pridanej hodnoty. Prípadné servisné či transakčné poplatky sú uvedené pred záväzným odoslaním objednávky; celková suma na úhradu je Návštevníkovi zobrazená pred potvrdením objednávky.","5.3 Vstupenka sa doručuje elektronicky na e-mailovú adresu uvedenú v objednávke a platí spolu s jedinečným kódom, ktorý sa pri vstupe kontroluje. Za ochranu vstupenky pred kopírovaním zodpovedá Návštevník; pri opakovanom použití toho istého kódu platí prvý uskutočnený vstup.","5.4 Za konanie podujatia, jeho obsah, priebeh, zmenu termínu, miesta alebo zrušenie zodpovedá výlučne Organizátor. Vrátenie vstupného pri zrušenom alebo presunutom podujatí vybavuje Organizátor.","5.5 Bezplatná rezervácia alebo prihlásenie na podujatie nezakladá nárok na vstup nad rámec kapacity oznámenej Organizátorom."]},{heading:"Čl. 6 — Odstúpenie od zmluvy a reklamácie",paragraphs:["6.1 Registrovaný používateľ, ktorý je spotrebiteľom, môže od Zmluvy o používaní Portálu kedykoľvek odstúpiť zrušením účtu, a to aj bez uvedenia dôvodu. Služba je bezplatná, preto s odstúpením nie sú spojené žiadne náklady.","6.2 Pri vstupenkách na podujatie sa právo spotrebiteľa odstúpiť od zmluvy do 14 dní neuplatňuje. Ide o poskytnutie služby súvisiacej s činnosťami v rámci voľného času, pri ktorej sa poskytovateľ zaväzuje poskytnúť plnenie v dohodnutom čase — výnimka podľa § 19 zákona č. 108/2024 Z. z. o ochrane spotrebiteľa.","6.3 Reklamáciu služieb Portálu možno uplatniť e-mailom na {email}. Prevádzkovateľ potvrdí jej prijatie, vybaví ju najneskôr do 30 dní od uplatnenia a o vybavení vydá písomný doklad.","6.4 Reklamáciu samotného podujatia (jeho priebehu, kvality, zrušenia) uplatňuje Návštevník u Organizátora, ktorý je zmluvnou stranou."]},{heading:"Čl. 7 — Prevádzka Portálu a zodpovednosť",paragraphs:["7.1 Prevádzkovateľ vyvíja primerané úsilie o nepretržitú dostupnosť Portálu, negarantuje ju však. Portál môže byť na nevyhnutný čas nedostupný z dôvodu údržby, aktualizácie alebo výpadku na strane tretích osôb.","7.2 Prevádzkovateľ je oprávnený meniť rozsah a podobu funkcií Portálu. Ak sa rozhodne prevádzku ukončiť, oznámi to Registrovaným používateľom najmenej 30 dní vopred.","7.3 Prevádzkovateľ nezodpovedá za škodu spôsobenú nedostupnosťou Portálu, stratou vloženého Obsahu ani konaním tretích osôb, ak ju nespôsobil úmyselne alebo z hrubej nedbanlivosti. Tým nie je dotknutá zodpovednosť za škodu na zdraví a ďalšia zodpovednosť, ktorú nemožno vylúčiť.","7.4 Používateľ nesmie Portál zaťažovať automatizovaným sťahovaním údajov nad bežnú mieru, obchádzať bezpečnostné prvky ani zasahovať do jeho technického riešenia."]},{heading:"Čl. 8 — Trvanie a zánik zmluvy",paragraphs:["8.1 Zmluva sa uzatvára na neurčitý čas.","8.2 Používateľ môže účet kedykoľvek zrušiť v nastaveniach účtu alebo žiadosťou na {email}.","8.3 Prevádzkovateľ môže účet obmedziť alebo zrušiť, ak Používateľ závažne alebo opakovane porušuje tieto podmienky, alebo ak je účet zjavne zneužívaný. Používateľa o tom informuje e-mailom spolu s dôvodom.","8.4 Zrušením účtu Zmluva zaniká. Informácie o podujatiach, ktoré sa už uskutočnili, môžu zostať v archíve Portálu; osobné údaje sa spracúvajú ďalej len v rozsahu opísanom v zásadách ochrany osobných údajov."]},{heading:"Čl. 9 — Ochrana osobných údajov",paragraphs:["9.1 Osobné údaje spracúva Prevádzkovateľ v rozsahu a spôsobom opísaným v dokumente Ochrana osobných údajov, ktorý je informačnou súčasťou týchto podmienok.","9.2 Spracúvanie údajov nevyhnutných na vedenie účtu a poskytovanie služieb Portálu sa zakladá na plnení tejto Zmluvy, nie na súhlase — nedá sa preto samostatne odvolať, kým účet trvá."]},{heading:"Čl. 10 — Alternatívne riešenie sporov",paragraphs:["10.1 Spotrebiteľ, ktorý nie je spokojný so spôsobom vybavenia reklamácie alebo sa domnieva, že Prevádzkovateľ porušil jeho práva, môže požiadať o nápravu na {email}.","10.2 Ak Prevádzkovateľ na žiadosť odpovie zamietavo alebo na ňu neodpovie do 30 dní, spotrebiteľ má právo podať návrh na začatie alternatívneho riešenia sporu podľa zákona č. 391/2015 Z. z. o alternatívnom riešení spotrebiteľských sporov.","10.3 Príslušným subjektom je Slovenská obchodná inšpekcia (Ústredný inšpektorát SOI, Bajkalská 21/A, 827 99 Bratislava, www.soi.sk) alebo iná oprávnená právnická osoba zapísaná v zozname subjektov alternatívneho riešenia sporov, ktorý vedie Ministerstvo hospodárstva SR. Spotrebiteľ si môže vybrať, na ktorý z nich sa obráti.","10.4 Alternatívne riešenie sporu je pre spotrebiteľa bezplatné alebo spoplatnené sumou najviac 5 eur. Právo obrátiť sa na súd tým nie je dotknuté."]},{heading:"Čl. 11 — Záverečné ustanovenia",paragraphs:["11.1 Právne vzťahy neupravené týmito podmienkami sa spravujú právnym poriadkom Slovenskej republiky, najmä Občianskym zákonníkom, zákonom č. 108/2024 Z. z. o ochrane spotrebiteľa a zákonom č. 22/2004 Z. z. o elektronickom obchode.","11.2 Prevádzkovateľ je oprávnený tieto podmienky meniť, najmä pri zmene právnych predpisov alebo rozsahu služieb. O zmene informuje Registrovaných používateľov e-mailom alebo oznamom na Portáli najmenej 15 dní pred účinnosťou nového znenia.","11.3 Ak Používateľ so zmenou nesúhlasí, môže do dňa jej účinnosti zrušiť účet. Používaním Portálu po tomto dni zmenu prijíma.","11.4 Ak sa niektoré ustanovenie týchto podmienok stane neplatným alebo neúčinným, ostatné ustanovenia zostávajú v platnosti.","11.5 Tieto podmienky sú vyhotovené v slovenskom jazyku; znenia v iných jazykoch sú informatívnym prekladom a v prípade rozporu je rozhodujúce slovenské znenie.","11.6 Toto znenie nadobúda účinnosť {effectiveFrom} a nahrádza všetky predchádzajúce znenia (verzia {version})."]}]},privacy:{title:"Ochrana osobných údajov",perex:"Tento dokument vysvetľuje, aké osobné údaje o vás portál {site} spracúva, na aký účel, ako dlho a aké máte práva. Postupujeme podľa nariadenia (EÚ) 2016/679 (GDPR) a zákona č. 18/2018 Z. z. o ochrane osobných údajov. Znenie je účinné od {effectiveFrom} (verzia {version}).",sections:[{heading:"1. Kto údaje spracúva",paragraphs:["Prevádzkovateľom v zmysle GDPR je {name}, so sídlom {address}, IČO: {ico}, {registration}.","Vo veciach ochrany osobných údajov nás kontaktujte na {email} alebo písomne na adrese sídla."]},{heading:"2. Aké údaje spracúvame",paragraphs:["Registračné údaje — e-mailová adresa, meno alebo názov, heslo (uložené výhradne v podobe nečitateľného odtlačku) a spôsob registrácie (e-mail, Google, Facebook).","Údaje o súhlase — dátum a verzia obchodných podmienok, s ktorými ste pri registrácii súhlasili.","Profilové a fakturačné údaje organizátora — názov, kontaktné a fakturačné údaje, ak ich zadáte.","Obsah, ktorý zverejníte — podujatia, miesta, fotografie, plagáty a texty vrátane kontaktov, ktoré v nich uvediete.","Komunikácia — obsah správ odoslaných cez Portál a e-mailovej komunikácie s nami.","Údaje o vstupenkách — objednané vstupenky, ich stav a záznam o vstupe na podujatie.","Technické údaje — IP adresa, typ a jazyk prehliadača, dátum a čas prístupu, záznamy o prihlásení a o chybách aplikácie."]},{heading:"3. Na aký účel a na akom právnom základe",paragraphs:["Vedenie používateľského účtu a poskytovanie funkcií Portálu — plnenie zmluvy podľa čl. 6 ods. 1 písm. b) GDPR. Poskytnutie týchto údajov je nevyhnutné; bez nich účet nevznikne.","Zverejnenie vami vloženého obsahu vrátane jeho zobrazenia vo vyhľadávačoch — plnenie zmluvy podľa čl. 6 ods. 1 písm. b) GDPR.","Sprostredkovanie vstupeniek, ich doručenie a kontrola pri vstupe — plnenie zmluvy podľa čl. 6 ods. 1 písm. b) GDPR; údaje potrebné na vstup sa odovzdávajú organizátorovi podujatia.","Overenie e-mailovej adresy, zabezpečenie účtov a ochrana pred zneužitím a spamom — oprávnený záujem podľa čl. 6 ods. 1 písm. f) GDPR.","Preukázanie udeleného súhlasu s obchodnými podmienkami — plnenie zákonnej povinnosti podľa čl. 6 ods. 1 písm. c) v spojení s čl. 7 ods. 1 GDPR.","Vedenie účtovníctva a plnenie daňových povinností pri platených službách — zákonná povinnosť podľa čl. 6 ods. 1 písm. c) GDPR.","Zasielanie noviniek a upozornení na podujatia, ak si ich vyžiadate — súhlas podľa čl. 6 ods. 1 písm. a) GDPR, ktorý môžete kedykoľvek odvolať bez vplyvu na zákonnosť spracúvania pred odvolaním.","Uplatňovanie alebo obhajovanie právnych nárokov — oprávnený záujem podľa čl. 6 ods. 1 písm. f) GDPR."]},{heading:"4. Ako dlho údaje uchovávame",paragraphs:["Údaje účtu — po dobu jeho trvania a následne najviac 1 rok od zrušenia účtu, kvôli prípadným nárokom z používania Portálu.","Neoverená registrácia — najviac do uplynutia platnosti overovacieho odkazu (48 hodín), potom sa automaticky vymaže.","Doklad o súhlase s podmienkami — po dobu trvania účtu a 1 rok po jeho zrušení, spolu s údajmi účtu.","Zverejnený obsah o podujatiach — aj po zrušení účtu môže zostať v archíve Portálu, spravidla bez kontaktných údajov na fyzické osoby.","Údaje o vstupenkách a účtovné doklady — 10 rokov, ak to vyžadujú daňové a účtovné predpisy.","Technické záznamy — spravidla 12 mesiacov."]},{heading:"5. Komu údaje sprístupňujeme",paragraphs:["Poskytovateľom technického zázemia — hosting a serverová infraštruktúra, odosielanie e-mailov, prípadne platobná brána a IT podpora. Títo príjemcovia konajú ako sprostredkovatelia na základe zmluvy podľa čl. 28 GDPR.","Organizátorovi podujatia — v rozsahu potrebnom na rezerváciu, vstupenku a vstup na podujatie.","Účtovníkovi a poradcom — v rozsahu potrebnom na plnenie zákonných povinností.","Orgánom verejnej moci — iba ak nám to ukladá právny predpis.","Osobné údaje nepredávame a neposkytujeme tretím stranám na ich vlastné marketingové účely."]},{heading:"6. Prenos do tretích krajín",paragraphs:["Údaje spracúvame v rámci Európskej únie a Európskeho hospodárskeho priestoru.","Ak by pri niektorej službe (napríklad pri prihlásení cez účet Google alebo Facebook) došlo k prenosu mimo EHP, deje sa tak na základe rozhodnutia Komisie o primeranosti alebo štandardných zmluvných doložiek schválených Európskou komisiou."]},{heading:"7. Vaše práva",paragraphs:["Máte právo na prístup k svojim údajom a na kópiu spracúvaných údajov.","Máte právo na opravu nesprávnych a doplnenie neúplných údajov.","Máte právo na vymazanie údajov, ak už nie sú potrebné a nebráni tomu zákonná povinnosť ich uchovávať.","Máte právo na obmedzenie spracúvania a právo na prenosnosť údajov, ktoré ste nám poskytli.","Máte právo namietať proti spracúvaniu založenému na oprávnenom záujme a právo kedykoľvek odvolať súhlas tam, kde je právnym základom.","Žiadosti posielajte na {email}. Odpovieme najneskôr do jedného mesiaca od doručenia žiadosti.","Máte právo podať sťažnosť dozornému orgánu: Úrad na ochranu osobných údajov Slovenskej republiky, Hraničná 12, 820 07 Bratislava 27, www.dataprotection.gov.sk."]},{heading:"8. Automatizované rozhodovanie",paragraphs:["Nevykonávame automatizované rozhodovanie ani profilovanie, ktoré by malo pre vás právne účinky alebo vás podobne významne ovplyvňovalo."]},{heading:"9. Súbory cookie a miestne úložisko",paragraphs:["Portál používa nevyhnutné cookies a miestne úložisko prehliadača na prihlásenie, bezpečnosť a zapamätanie zvoleného jazyka. Bez nich by Portál nefungoval, preto sa na ne súhlas nevyžaduje.","Ak nasadíme analytické alebo marketingové cookies, vyžiadame si na ne váš súhlas vopred a bude sa dať kedykoľvek odvolať.","Uložené cookies môžete kedykoľvek vymazať v nastaveniach svojho prehliadača; niektoré funkcie Portálu potom nemusia fungovať."]},{heading:"10. Zmeny tohto dokumentu",paragraphs:["Aktuálne znenie je vždy dostupné na tejto stránke. O podstatných zmenách informujeme registrovaných používateľov e-mailom alebo oznamom na Portáli.","Toto znenie je účinné od {effectiveFrom} (verzia {version}). Rozhodujúce je slovenské znenie; ostatné jazykové verzie sú informatívnym prekladom."]}]}},V={terms:{title:"Obchodní podmínky",perex:"Tyto obchodní podmínky upravují práva a povinnosti při používání portálu {site}. Znění je účinné od {effectiveFrom} (verze {version}). Rozhodující je slovenské znění.",sections:[{heading:"Čl. 1 — Provozovatel",paragraphs:["1.1 Provozovatelem portálu {site} (dále jen „Portál“) je {name}, se sídlem {address}, IČO: {ico}, {dic}, {registration} (dále jen „Provozovatel“).","1.2 Kontaktní údaje: e-mail {email}, telefon {phone}.","1.3 Orgánem dozoru je Slovenská obchodní inspekce — {soi}."]},{heading:"Čl. 2 — Vymezení pojmů",paragraphs:["2.1 Portál — webová aplikace dostupná na adrese {site}, která zveřejňuje informace o kulturních, společenských, sportovních a jiných akcích a související služby.","2.2 Uživatel — fyzická nebo právnická osoba, která Portál používá, i bez registrace.","2.3 Registrovaný uživatel — Uživatel, který má na Portálu vytvořený účet.","2.4 Pořadatel — Registrovaný uživatel, který na Portálu zveřejňuje akce, případně přes Portál nabízí vstupenky.","2.5 Návštěvník — Uživatel, který si přes Portál rezervuje nebo koupí vstupenku, případně se na akci přihlásí.","2.6 Obsah — texty, fotografie, plakáty, odkazy a další údaje, které na Portál vloží Uživatel.","2.7 Smlouva — smlouva o poskytování služeb Portálu mezi Provozovatelem a Registrovaným uživatelem, jejímž obsahem jsou tyto podmínky."]},{heading:"Čl. 3 — Registrace a uživatelský účet",paragraphs:["3.1 Registrace je bezplatná a dobrovolná. Prohlížení zveřejněných akcí je možné i bez ní.","3.2 Účet si může vytvořit osoba starší 16 let. Za mladší osobu může jednat pouze její zákonný zástupce.","3.3 Registraci Uživatel dokončí vyplněním formuláře a zaškrtnutím souhlasu s těmito podmínkami. Smlouva vzniká ověřením e-mailové adresy, případně prvním přihlášením přes účet Google nebo Facebook.","3.4 Uživatel uvádí pravdivé a aktuální údaje a odpovídá za utajení přístupových údajů k účtu. Podezření na zneužití účtu neprodleně oznámí na {email}.","3.5 Účet je nepřenosný. Uživatel odpovídá za jednání, ke kterému došlo prostřednictvím jeho účtu.","3.6 Registruje-li se Uživatel jako Pořadatel jménem právnické osoby, prohlašuje, že je oprávněn za ni jednat."]},{heading:"Čl. 4 — Obsah zveřejňovaný Uživatelem",paragraphs:["4.1 Za správnost, zákonnost a aktuálnost Obsahu odpovídá Uživatel, který jej vložil. Provozovatel Obsah nevytváří a neručí za jeho úplnost ani pravdivost.","4.2 Vložením Obsahu uděluje Uživatel Provozovateli bezúplatnou, nevýhradní a územně neomezenou licenci k jeho zobrazování, rozmnožování, úpravě velikosti a šíření v rozsahu potřebném pro provoz a propagaci Portálu včetně náhledů ve vyhledávačích a na sociálních sítích, a to po dobu zveřejnění Obsahu na Portálu.","4.3 Uživatel prohlašuje, že je oprávněn takovou licenci udělit a že Obsah neporušuje práva třetích osob, zejména autorská práva, práva na ochranu osobnosti a práva k ochranným známkám.","4.4 Zakázán je Obsah, který je v rozporu s právním řádem Slovenské republiky nebo s dobrými mravy, zejména nenávistný, hanlivý, klamavý, zásadně nesouvisející s akcemi, propagující násilí nebo nevhodný pro nezletilé.","4.5 Provozovatel je oprávněn Obsah porušující tyto podmínky nezveřejnit, upravit jeho zařazení do kategorií nebo jej odstranit. O odstranění Uživatele informuje; Uživatel může proti tomu podat námitku na {email}.","4.6 Provozovatel není povinen Obsah předem kontrolovat. Na oznámení o protiprávním Obsahu doručené na {email} reaguje bez zbytečného odkladu."]},{heading:"Čl. 5 — Vstupenky a platby",paragraphs:["5.1 Umožňuje-li Portál rezervaci nebo prodej vstupenek, Provozovatel jedná jako zprostředkovatel jménem a na účet Pořadatele. Smlouva o účasti na akci vzniká mezi Návštěvníkem a Pořadatelem, nikoli s Provozovatelem.","5.2 Cena vstupenky je uvedena včetně daně z přidané hodnoty. Případné servisní či transakční poplatky jsou uvedeny před závazným odesláním objednávky; celková částka k úhradě je Návštěvníkovi zobrazena před potvrzením objednávky.","5.3 Vstupenka se doručuje elektronicky na e-mailovou adresu uvedenou v objednávce a platí spolu s jedinečným kódem, který se při vstupu kontroluje. Za ochranu vstupenky před kopírováním odpovídá Návštěvník; při opakovaném použití téhož kódu platí první uskutečněný vstup.","5.4 Za konání akce, její obsah, průběh, změnu termínu, místa nebo zrušení odpovídá výhradně Pořadatel. Vrácení vstupného u zrušené nebo přesunuté akce vyřizuje Pořadatel.","5.5 Bezplatná rezervace nebo přihlášení na akci nezakládá nárok na vstup nad rámec kapacity oznámené Pořadatelem."]},{heading:"Čl. 6 — Odstoupení od smlouvy a reklamace",paragraphs:["6.1 Registrovaný uživatel, který je spotřebitelem, může od Smlouvy o používání Portálu kdykoli odstoupit zrušením účtu, a to i bez uvedení důvodu. Služba je bezplatná, proto s odstoupením nejsou spojeny žádné náklady.","6.2 U vstupenek na akci se právo spotřebitele odstoupit od smlouvy do 14 dnů neuplatňuje. Jde o poskytnutí služby související s činnostmi v rámci volného času, u které se poskytovatel zavazuje poskytnout plnění v dohodnutém čase — výjimka podle § 19 zákona č. 108/2024 Z. z. o ochraně spotřebitele.","6.3 Reklamaci služeb Portálu lze uplatnit e-mailem na {email}. Provozovatel potvrdí její přijetí, vyřídí ji nejpozději do 30 dnů od uplatnění a o vyřízení vydá písemný doklad.","6.4 Reklamaci samotné akce (jejího průběhu, kvality, zrušení) uplatňuje Návštěvník u Pořadatele, který je smluvní stranou."]},{heading:"Čl. 7 — Provoz Portálu a odpovědnost",paragraphs:["7.1 Provozovatel vyvíjí přiměřené úsilí o nepřetržitou dostupnost Portálu, negarantuje ji však. Portál může být na nezbytnou dobu nedostupný z důvodu údržby, aktualizace nebo výpadku na straně třetích osob.","7.2 Provozovatel je oprávněn měnit rozsah a podobu funkcí Portálu. Rozhodne-li se provoz ukončit, oznámí to Registrovaným uživatelům nejméně 30 dnů předem.","7.3 Provozovatel neodpovídá za škodu způsobenou nedostupností Portálu, ztrátou vloženého Obsahu ani jednáním třetích osob, pokud ji nezpůsobil úmyslně nebo z hrubé nedbalosti. Tím není dotčena odpovědnost za škodu na zdraví a další odpovědnost, kterou nelze vyloučit.","7.4 Uživatel nesmí Portál zatěžovat automatizovaným stahováním údajů nad běžnou míru, obcházet bezpečnostní prvky ani zasahovat do jeho technického řešení."]},{heading:"Čl. 8 — Trvání a zánik smlouvy",paragraphs:["8.1 Smlouva se uzavírá na dobu neurčitou.","8.2 Uživatel může účet kdykoli zrušit v nastavení účtu nebo žádostí na {email}.","8.3 Provozovatel může účet omezit nebo zrušit, pokud Uživatel závažně nebo opakovaně porušuje tyto podmínky, nebo je-li účet zjevně zneužíván. Uživatele o tom informuje e-mailem spolu s důvodem.","8.4 Zrušením účtu Smlouva zaniká. Informace o akcích, které se již uskutečnily, mohou zůstat v archivu Portálu; osobní údaje se dále zpracovávají pouze v rozsahu popsaném v zásadách ochrany osobních údajů."]},{heading:"Čl. 9 — Ochrana osobních údajů",paragraphs:["9.1 Osobní údaje zpracovává Provozovatel v rozsahu a způsobem popsaným v dokumentu Ochrana osobních údajů, který je informační součástí těchto podmínek.","9.2 Zpracování údajů nezbytných pro vedení účtu a poskytování služeb Portálu se zakládá na plnění této Smlouvy, nikoli na souhlasu — nelze je proto samostatně odvolat, dokud účet trvá."]},{heading:"Čl. 10 — Alternativní řešení sporů",paragraphs:["10.1 Spotřebitel, který není spokojen se způsobem vyřízení reklamace nebo se domnívá, že Provozovatel porušil jeho práva, může požádat o nápravu na {email}.","10.2 Odpoví-li Provozovatel na žádost zamítavě nebo neodpoví-li do 30 dnů, má spotřebitel právo podat návrh na zahájení alternativního řešení sporu podle zákona č. 391/2015 Z. z. o alternativním řešení spotřebitelských sporů.","10.3 Příslušným subjektem je Slovenská obchodní inspekce (Ústredný inšpektorát SOI, Bajkalská 21/A, 827 99 Bratislava, www.soi.sk) nebo jiná oprávněná právnická osoba zapsaná v seznamu subjektů alternativního řešení sporů, který vede Ministerstvo hospodářství SR. Spotřebitel si může vybrat, na který z nich se obrátí.","10.4 Alternativní řešení sporu je pro spotřebitele bezplatné nebo zpoplatněné částkou nejvýše 5 eur. Právo obrátit se na soud tím není dotčeno."]},{heading:"Čl. 11 — Závěrečná ustanovení",paragraphs:["11.1 Právní vztahy neupravené těmito podmínkami se řídí právním řádem Slovenské republiky, zejména Občanským zákoníkem, zákonem č. 108/2024 Z. z. o ochraně spotřebitele a zákonem č. 22/2004 Z. z. o elektronickém obchodu.","11.2 Provozovatel je oprávněn tyto podmínky měnit, zejména při změně právních předpisů nebo rozsahu služeb. O změně informuje Registrované uživatele e-mailem nebo oznámením na Portálu nejméně 15 dnů před účinností nového znění.","11.3 Nesouhlasí-li Uživatel se změnou, může do dne její účinnosti zrušit účet. Používáním Portálu po tomto dni změnu přijímá.","11.4 Stane-li se některé ustanovení těchto podmínek neplatným nebo neúčinným, ostatní ustanovení zůstávají v platnosti.","11.5 Tyto podmínky jsou vyhotoveny ve slovenském jazyce; znění v jiných jazycích jsou informativním překladem a v případě rozporu je rozhodující slovenské znění.","11.6 Toto znění nabývá účinnosti {effectiveFrom} a nahrazuje všechna předchozí znění (verze {version})."]}]},privacy:{title:"Ochrana osobních údajů",perex:"Tento dokument vysvětluje, jaké osobní údaje o vás portál {site} zpracovává, za jakým účelem, jak dlouho a jaká máte práva. Postupujeme podle nařízení (EU) 2016/679 (GDPR) a zákona č. 18/2018 Z. z. o ochraně osobních údajů. Znění je účinné od {effectiveFrom} (verze {version}).",sections:[{heading:"1. Kdo údaje zpracovává",paragraphs:["Správcem ve smyslu GDPR je {name}, se sídlem {address}, IČO: {ico}, {registration}.","Ve věcech ochrany osobních údajů nás kontaktujte na {email} nebo písemně na adrese sídla."]},{heading:"2. Jaké údaje zpracováváme",paragraphs:["Registrační údaje — e-mailová adresa, jméno nebo název, heslo (uložené výhradně v podobě nečitelného otisku) a způsob registrace (e-mail, Google, Facebook).","Údaje o souhlasu — datum a verze obchodních podmínek, se kterými jste při registraci souhlasili.","Profilové a fakturační údaje pořadatele — název, kontaktní a fakturační údaje, pokud je zadáte.","Obsah, který zveřejníte — akce, místa, fotografie, plakáty a texty včetně kontaktů, které v nich uvedete.","Komunikace — obsah zpráv odeslaných přes Portál a e-mailové komunikace s námi.","Údaje o vstupenkách — objednané vstupenky, jejich stav a záznam o vstupu na akci.","Technické údaje — IP adresa, typ a jazyk prohlížeče, datum a čas přístupu, záznamy o přihlášení a o chybách aplikace."]},{heading:"3. Za jakým účelem a na jakém právním základě",paragraphs:["Vedení uživatelského účtu a poskytování funkcí Portálu — plnění smlouvy podle čl. 6 odst. 1 písm. b) GDPR. Poskytnutí těchto údajů je nezbytné; bez nich účet nevznikne.","Zveřejnění vámi vloženého obsahu včetně jeho zobrazení ve vyhledávačích — plnění smlouvy podle čl. 6 odst. 1 písm. b) GDPR.","Zprostředkování vstupenek, jejich doručení a kontrola při vstupu — plnění smlouvy podle čl. 6 odst. 1 písm. b) GDPR; údaje potřebné ke vstupu se předávají pořadateli akce.","Ověření e-mailové adresy, zabezpečení účtů a ochrana před zneužitím a spamem — oprávněný zájem podle čl. 6 odst. 1 písm. f) GDPR.","Prokázání uděleného souhlasu s obchodními podmínkami — plnění právní povinnosti podle čl. 6 odst. 1 písm. c) ve spojení s čl. 7 odst. 1 GDPR.","Vedení účetnictví a plnění daňových povinností u placených služeb — právní povinnost podle čl. 6 odst. 1 písm. c) GDPR.","Zasílání novinek a upozornění na akce, pokud si je vyžádáte — souhlas podle čl. 6 odst. 1 písm. a) GDPR, který můžete kdykoli odvolat bez vlivu na zákonnost zpracování před odvoláním.","Uplatňování nebo obhajoba právních nároků — oprávněný zájem podle čl. 6 odst. 1 písm. f) GDPR."]},{heading:"4. Jak dlouho údaje uchováváme",paragraphs:["Údaje účtu — po dobu jeho trvání a následně nejvýše 1 rok od zrušení účtu, kvůli případným nárokům z používání Portálu.","Neověřená registrace — nejdéle do uplynutí platnosti ověřovacího odkazu (48 hodin), poté se automaticky vymaže.","Doklad o souhlasu s podmínkami — po dobu trvání účtu a 1 rok po jeho zrušení, spolu s údaji účtu.","Zveřejněný obsah o akcích — i po zrušení účtu může zůstat v archivu Portálu, zpravidla bez kontaktních údajů na fyzické osoby.","Údaje o vstupenkách a účetní doklady — 10 let, vyžadují-li to daňové a účetní předpisy.","Technické záznamy — zpravidla 12 měsíců."]},{heading:"5. Komu údaje zpřístupňujeme",paragraphs:["Poskytovatelům technického zázemí — hosting a serverová infrastruktura, odesílání e-mailů, případně platební brána a IT podpora. Tito příjemci jednají jako zpracovatelé na základě smlouvy podle čl. 28 GDPR.","Pořadateli akce — v rozsahu potřebném pro rezervaci, vstupenku a vstup na akci.","Účetnímu a poradcům — v rozsahu potřebném pro plnění zákonných povinností.","Orgánům veřejné moci — pouze pokud nám to ukládá právní předpis.","Osobní údaje neprodáváme a neposkytujeme třetím stranám pro jejich vlastní marketingové účely."]},{heading:"6. Předávání do třetích zemí",paragraphs:["Údaje zpracováváme v rámci Evropské unie a Evropského hospodářského prostoru.","Pokud by u některé služby (například při přihlášení přes účet Google nebo Facebook) došlo k předání mimo EHP, děje se tak na základě rozhodnutí Komise o odpovídající ochraně nebo standardních smluvních doložek schválených Evropskou komisí."]},{heading:"7. Vaše práva",paragraphs:["Máte právo na přístup ke svým údajům a na kopii zpracovávaných údajů.","Máte právo na opravu nesprávných a doplnění neúplných údajů.","Máte právo na výmaz údajů, pokud již nejsou potřebné a nebrání tomu zákonná povinnost je uchovávat.","Máte právo na omezení zpracování a právo na přenositelnost údajů, které jste nám poskytli.","Máte právo vznést námitku proti zpracování založenému na oprávněném zájmu a právo kdykoli odvolat souhlas tam, kde je právním základem.","Žádosti posílejte na {email}. Odpovíme nejpozději do jednoho měsíce od doručení žádosti.","Máte právo podat stížnost dozorovému úřadu: Úrad na ochranu osobných údajov Slovenskej republiky, Hraničná 12, 820 07 Bratislava 27, www.dataprotection.gov.sk."]},{heading:"8. Automatizované rozhodování",paragraphs:["Neprovádíme automatizované rozhodování ani profilování, které by pro vás mělo právní účinky nebo vás podobně významně ovlivňovalo."]},{heading:"9. Soubory cookie a místní úložiště",paragraphs:["Portál používá nezbytné cookies a místní úložiště prohlížeče pro přihlášení, bezpečnost a zapamatování zvoleného jazyka. Bez nich by Portál nefungoval, proto se na ně souhlas nevyžaduje.","Nasadíme-li analytické nebo marketingové cookies, vyžádáme si na ně váš souhlas předem a půjde jej kdykoli odvolat.","Uložené cookies můžete kdykoli smazat v nastavení svého prohlížeče; některé funkce Portálu pak nemusí fungovat."]},{heading:"10. Změny tohoto dokumentu",paragraphs:["Aktuální znění je vždy dostupné na této stránce. O podstatných změnách informujeme registrované uživatele e-mailem nebo oznámením na Portálu.","Toto znění je účinné od {effectiveFrom} (verze {version}). Rozhodující je slovenské znění; ostatní jazykové verze jsou informativním překladem."]}]}},T={terms:{title:"Allgemeine Geschäftsbedingungen",perex:"Diese Geschäftsbedingungen regeln die Rechte und Pflichten bei der Nutzung des Portals {site}. Diese Fassung gilt ab {effectiveFrom} (Version {version}). Maßgeblich ist der slowakische Wortlaut.",sections:[{heading:"Art. 1 — Betreiber",paragraphs:["1.1 Betreiber des Portals {site} (nachfolgend „Portal“) ist {name}, Sitz {address}, Ident.-Nr. (IČO): {ico}, {dic}, {registration} (nachfolgend „Betreiber“).","1.2 Kontakt: E-Mail {email}, Telefon {phone}.","1.3 Aufsichtsbehörde ist die Slowakische Handelsinspektion (Slovenská obchodná inšpekcia) — {soi}."]},{heading:"Art. 2 — Begriffsbestimmungen",paragraphs:["2.1 Portal — die unter {site} erreichbare Webanwendung, die Informationen über kulturelle, gesellschaftliche, sportliche und sonstige Veranstaltungen sowie damit verbundene Dienste veröffentlicht.","2.2 Nutzer — eine natürliche oder juristische Person, die das Portal nutzt, auch ohne Registrierung.","2.3 Registrierter Nutzer — ein Nutzer mit einem Konto auf dem Portal.","2.4 Veranstalter — ein registrierter Nutzer, der auf dem Portal Veranstaltungen veröffentlicht oder darüber Tickets anbietet.","2.5 Besucher — ein Nutzer, der über das Portal ein Ticket reserviert oder kauft bzw. sich für eine Veranstaltung anmeldet.","2.6 Inhalt — Texte, Fotos, Plakate, Links und weitere Daten, die ein Nutzer in das Portal einstellt.","2.7 Vertrag — der Vertrag über die Erbringung der Portalleistungen zwischen dem Betreiber und einem registrierten Nutzer, dessen Inhalt diese Bedingungen bilden."]},{heading:"Art. 3 — Registrierung und Nutzerkonto",paragraphs:["3.1 Die Registrierung ist kostenlos und freiwillig. Veröffentlichte Veranstaltungen können auch ohne sie angesehen werden.","3.2 Ein Konto kann eine Person ab 16 Jahren anlegen. Für jüngere Personen darf nur deren gesetzlicher Vertreter handeln.","3.3 Der Nutzer schließt die Registrierung ab, indem er das Formular ausfüllt und sein Einverständnis mit diesen Bedingungen ankreuzt. Der Vertrag kommt mit der Bestätigung der E-Mail-Adresse bzw. mit der ersten Anmeldung über ein Google- oder Facebook-Konto zustande.","3.4 Der Nutzer macht wahrheitsgemäße und aktuelle Angaben und ist für die Geheimhaltung seiner Zugangsdaten verantwortlich. Den Verdacht eines Missbrauchs meldet er unverzüglich an {email}.","3.5 Das Konto ist nicht übertragbar. Der Nutzer haftet für Handlungen, die über sein Konto erfolgen.","3.6 Registriert sich ein Nutzer als Veranstalter im Namen einer juristischen Person, erklärt er, zu deren Vertretung berechtigt zu sein."]},{heading:"Art. 4 — Vom Nutzer veröffentlichte Inhalte",paragraphs:["4.1 Für Richtigkeit, Rechtmäßigkeit und Aktualität des Inhalts haftet der Nutzer, der ihn eingestellt hat. Der Betreiber erstellt die Inhalte nicht und übernimmt keine Gewähr für deren Vollständigkeit oder Wahrheitsgehalt.","4.2 Mit dem Einstellen von Inhalten räumt der Nutzer dem Betreiber ein unentgeltliches, nicht ausschließliches und räumlich unbeschränktes Recht ein, diese im für Betrieb und Bewerbung des Portals erforderlichen Umfang anzuzeigen, zu vervielfältigen, in der Größe anzupassen und zu verbreiten, einschließlich Vorschauen in Suchmaschinen und sozialen Netzwerken, und zwar für die Dauer der Veröffentlichung auf dem Portal.","4.3 Der Nutzer erklärt, zur Einräumung dieses Rechts befugt zu sein und dass der Inhalt keine Rechte Dritter verletzt, insbesondere Urheber-, Persönlichkeits- und Markenrechte.","4.4 Untersagt sind Inhalte, die gegen die Rechtsordnung der Slowakischen Republik oder die guten Sitten verstoßen, insbesondere hetzerische, ehrverletzende, irreführende, grundsätzlich veranstaltungsfremde, gewaltverherrlichende oder für Minderjährige ungeeignete Inhalte.","4.5 Der Betreiber ist berechtigt, Inhalte, die gegen diese Bedingungen verstoßen, nicht zu veröffentlichen, ihre Kategorisierung zu ändern oder sie zu entfernen. Über eine Entfernung informiert er den Nutzer; dieser kann unter {email} Einspruch erheben.","4.6 Der Betreiber ist nicht verpflichtet, Inhalte vorab zu prüfen. Auf Meldungen rechtswidriger Inhalte an {email} reagiert er unverzüglich."]},{heading:"Art. 5 — Tickets und Zahlungen",paragraphs:["5.1 Ermöglicht das Portal die Reservierung oder den Verkauf von Tickets, handelt der Betreiber als Vermittler im Namen und für Rechnung des Veranstalters. Der Vertrag über die Teilnahme an der Veranstaltung kommt zwischen Besucher und Veranstalter zustande, nicht mit dem Betreiber.","5.2 Der Ticketpreis wird einschließlich Mehrwertsteuer angegeben. Etwaige Service- oder Transaktionsgebühren werden vor der verbindlichen Bestellung ausgewiesen; der Gesamtbetrag wird dem Besucher vor der Bestätigung der Bestellung angezeigt.","5.3 Das Ticket wird elektronisch an die in der Bestellung angegebene E-Mail-Adresse zugestellt und gilt zusammen mit einem eindeutigen Code, der am Einlass geprüft wird. Für den Schutz des Tickets vor Kopieren haftet der Besucher; bei mehrfacher Verwendung desselben Codes gilt der erste Einlass.","5.4 Für das Zustandekommen der Veranstaltung, ihren Inhalt, Ablauf, Termin- und Ortsänderungen sowie die Absage haftet ausschließlich der Veranstalter. Die Erstattung des Eintrittsgelds bei abgesagten oder verschobenen Veranstaltungen wickelt der Veranstalter ab.","5.5 Eine kostenlose Reservierung oder Anmeldung begründet keinen Einlassanspruch über die vom Veranstalter angekündigte Kapazität hinaus."]},{heading:"Art. 6 — Widerruf und Reklamationen",paragraphs:["6.1 Ein registrierter Nutzer, der Verbraucher ist, kann vom Vertrag über die Nutzung des Portals jederzeit und ohne Angabe von Gründen durch Löschen seines Kontos zurücktreten. Die Leistung ist unentgeltlich, sodass hierfür keine Kosten anfallen.","6.2 Bei Veranstaltungstickets besteht kein 14-tägiges Widerrufsrecht. Es handelt sich um eine Dienstleistung im Zusammenhang mit Freizeitbetätigungen, bei der sich der Anbieter zur Leistung zu einem bestimmten Zeitpunkt verpflichtet — Ausnahme nach § 19 des Gesetzes Nr. 108/2024 Slg. über den Verbraucherschutz.","6.3 Reklamationen zu den Portalleistungen können per E-Mail an {email} geltend gemacht werden. Der Betreiber bestätigt den Eingang, erledigt die Reklamation spätestens innerhalb von 30 Tagen und stellt darüber einen schriftlichen Nachweis aus.","6.4 Reklamationen zur Veranstaltung selbst (Ablauf, Qualität, Absage) sind beim Veranstalter als Vertragspartner geltend zu machen."]},{heading:"Art. 7 — Betrieb des Portals und Haftung",paragraphs:["7.1 Der Betreiber bemüht sich in angemessenem Umfang um eine durchgehende Verfügbarkeit des Portals, garantiert sie jedoch nicht. Das Portal kann für die erforderliche Zeit wegen Wartung, Aktualisierung oder Ausfällen Dritter nicht erreichbar sein.","7.2 Der Betreiber darf Umfang und Gestalt der Portalfunktionen ändern. Beabsichtigt er, den Betrieb einzustellen, teilt er dies registrierten Nutzern mindestens 30 Tage im Voraus mit.","7.3 Der Betreiber haftet nicht für Schäden durch Nichtverfügbarkeit des Portals, Verlust eingestellter Inhalte oder Handlungen Dritter, sofern er sie nicht vorsätzlich oder grob fahrlässig verursacht hat. Die Haftung für Gesundheitsschäden und sonstige nicht ausschließbare Haftung bleibt unberührt.","7.4 Der Nutzer darf das Portal nicht über das übliche Maß hinaus durch automatisierten Datenabruf belasten, Sicherheitsvorkehrungen umgehen oder in seine technische Umsetzung eingreifen."]},{heading:"Art. 8 — Laufzeit und Beendigung",paragraphs:["8.1 Der Vertrag wird auf unbestimmte Zeit geschlossen.","8.2 Der Nutzer kann sein Konto jederzeit in den Kontoeinstellungen oder per Anfrage an {email} löschen.","8.3 Der Betreiber kann ein Konto einschränken oder löschen, wenn der Nutzer diese Bedingungen schwerwiegend oder wiederholt verletzt oder das Konto offensichtlich missbraucht wird. Er informiert den Nutzer per E-Mail unter Angabe des Grundes.","8.4 Mit der Löschung des Kontos endet der Vertrag. Informationen über bereits stattgefundene Veranstaltungen können im Archiv des Portals verbleiben; personenbezogene Daten werden nur noch im Umfang der Datenschutzhinweise verarbeitet."]},{heading:"Art. 9 — Schutz personenbezogener Daten",paragraphs:["9.1 Der Betreiber verarbeitet personenbezogene Daten in dem Umfang und auf die Weise, wie im Dokument Datenschutz beschrieben, das informativer Bestandteil dieser Bedingungen ist.","9.2 Die Verarbeitung der für Kontoführung und Leistungserbringung erforderlichen Daten beruht auf der Vertragserfüllung, nicht auf einer Einwilligung — sie kann daher nicht gesondert widerrufen werden, solange das Konto besteht."]},{heading:"Art. 10 — Alternative Streitbeilegung",paragraphs:["10.1 Ein Verbraucher, der mit der Erledigung seiner Reklamation nicht zufrieden ist oder der Ansicht ist, der Betreiber habe seine Rechte verletzt, kann unter {email} Abhilfe verlangen.","10.2 Antwortet der Betreiber ablehnend oder innerhalb von 30 Tagen gar nicht, hat der Verbraucher das Recht, einen Antrag auf alternative Streitbeilegung nach dem Gesetz Nr. 391/2015 Slg. über die alternative Beilegung von Verbraucherstreitigkeiten zu stellen.","10.3 Zuständige Stelle ist die Slowakische Handelsinspektion (Ústredný inšpektorát SOI, Bajkalská 21/A, 827 99 Bratislava, www.soi.sk) oder eine andere befugte juristische Person, die in der vom Wirtschaftsministerium der Slowakischen Republik geführten Liste der Stellen zur alternativen Streitbeilegung eingetragen ist. Der Verbraucher kann wählen, an wen er sich wendet.","10.4 Die alternative Streitbeilegung ist für den Verbraucher unentgeltlich oder mit höchstens 5 Euro bepreist. Das Recht, ein Gericht anzurufen, bleibt unberührt."]},{heading:"Art. 11 — Schlussbestimmungen",paragraphs:["11.1 Nicht geregelte Rechtsverhältnisse richten sich nach dem Recht der Slowakischen Republik, insbesondere dem Bürgerlichen Gesetzbuch, dem Gesetz Nr. 108/2024 Slg. über den Verbraucherschutz und dem Gesetz Nr. 22/2004 Slg. über den elektronischen Geschäftsverkehr.","11.2 Der Betreiber darf diese Bedingungen ändern, insbesondere bei Änderungen der Rechtsvorschriften oder des Leistungsumfangs. Über eine Änderung informiert er registrierte Nutzer mindestens 15 Tage vor Wirksamwerden der neuen Fassung per E-Mail oder Hinweis auf dem Portal.","11.3 Ist der Nutzer mit der Änderung nicht einverstanden, kann er sein Konto bis zum Tag ihres Wirksamwerdens löschen. Mit der weiteren Nutzung nach diesem Tag nimmt er die Änderung an.","11.4 Sollte eine Bestimmung dieser Bedingungen unwirksam werden, bleiben die übrigen Bestimmungen wirksam.","11.5 Diese Bedingungen sind in slowakischer Sprache abgefasst; Fassungen in anderen Sprachen sind eine informative Übersetzung, im Widerspruchsfall ist der slowakische Wortlaut maßgeblich.","11.6 Diese Fassung tritt am {effectiveFrom} in Kraft und ersetzt alle bisherigen Fassungen (Version {version})."]}]},privacy:{title:"Datenschutz",perex:"Dieses Dokument erklärt, welche personenbezogenen Daten das Portal {site} über Sie verarbeitet, zu welchem Zweck, wie lange und welche Rechte Sie haben. Wir handeln nach der Verordnung (EU) 2016/679 (DSGVO) und dem Gesetz Nr. 18/2018 Slg. über den Schutz personenbezogener Daten. Diese Fassung gilt ab {effectiveFrom} (Version {version}).",sections:[{heading:"1. Wer die Daten verarbeitet",paragraphs:["Verantwortlicher im Sinne der DSGVO ist {name}, Sitz {address}, Ident.-Nr. (IČO): {ico}, {registration}.","In Datenschutzangelegenheiten erreichen Sie uns unter {email} oder schriftlich an der Anschrift des Sitzes."]},{heading:"2. Welche Daten wir verarbeiten",paragraphs:["Registrierungsdaten — E-Mail-Adresse, Name oder Firma, Passwort (ausschließlich als unlesbarer Hash gespeichert) und Registrierungsart (E-Mail, Google, Facebook).","Einwilligungsnachweis — Datum und Version der Geschäftsbedingungen, denen Sie bei der Registrierung zugestimmt haben.","Profil- und Rechnungsdaten des Veranstalters — Name, Kontakt- und Rechnungsdaten, sofern Sie diese angeben.","Von Ihnen veröffentlichte Inhalte — Veranstaltungen, Orte, Fotos, Plakate und Texte einschließlich darin genannter Kontaktdaten.","Kommunikation — Inhalt der über das Portal gesendeten Nachrichten und der E-Mail-Korrespondenz mit uns.","Ticketdaten — bestellte Tickets, deren Status und der Einlassnachweis.","Technische Daten — IP-Adresse, Browsertyp und -sprache, Datum und Uhrzeit des Zugriffs, Anmeldeprotokolle und Fehlerprotokolle der Anwendung."]},{heading:"3. Zwecke und Rechtsgrundlagen",paragraphs:["Führung des Nutzerkontos und Bereitstellung der Portalfunktionen — Vertragserfüllung nach Art. 6 Abs. 1 lit. b DSGVO. Die Angabe dieser Daten ist erforderlich; ohne sie entsteht kein Konto.","Veröffentlichung der von Ihnen eingestellten Inhalte einschließlich ihrer Anzeige in Suchmaschinen — Vertragserfüllung nach Art. 6 Abs. 1 lit. b DSGVO.","Vermittlung von Tickets, deren Zustellung und Prüfung am Einlass — Vertragserfüllung nach Art. 6 Abs. 1 lit. b DSGVO; die für den Einlass nötigen Daten werden an den Veranstalter übermittelt.","Bestätigung der E-Mail-Adresse, Absicherung der Konten und Schutz vor Missbrauch und Spam — berechtigtes Interesse nach Art. 6 Abs. 1 lit. f DSGVO.","Nachweis der erteilten Zustimmung zu den Geschäftsbedingungen — rechtliche Verpflichtung nach Art. 6 Abs. 1 lit. c in Verbindung mit Art. 7 Abs. 1 DSGVO.","Buchführung und Erfüllung steuerlicher Pflichten bei kostenpflichtigen Leistungen — rechtliche Verpflichtung nach Art. 6 Abs. 1 lit. c DSGVO.","Versand von Neuigkeiten und Veranstaltungshinweisen, sofern Sie diese anfordern — Einwilligung nach Art. 6 Abs. 1 lit. a DSGVO, jederzeit widerrufbar ohne Auswirkung auf die Rechtmäßigkeit der bisherigen Verarbeitung.","Geltendmachung oder Abwehr von Rechtsansprüchen — berechtigtes Interesse nach Art. 6 Abs. 1 lit. f DSGVO."]},{heading:"4. Wie lange wir die Daten speichern",paragraphs:["Kontodaten — für die Dauer des Kontos und danach höchstens 1 Jahr ab Löschung, wegen möglicher Ansprüche aus der Nutzung des Portals.","Nicht bestätigte Registrierung — längstens bis zum Ablauf des Bestätigungslinks (48 Stunden), danach automatische Löschung.","Einwilligungsnachweis — für die Dauer des Kontos und 1 Jahr nach dessen Löschung, gemeinsam mit den Kontodaten.","Veröffentlichte Veranstaltungsinhalte — können auch nach Löschung des Kontos im Archiv des Portals verbleiben, in der Regel ohne Kontaktdaten natürlicher Personen.","Ticketdaten und Buchhaltungsbelege — 10 Jahre, soweit steuer- und buchhaltungsrechtlich erforderlich.","Technische Protokolle — in der Regel 12 Monate."]},{heading:"5. An wen wir Daten weitergeben",paragraphs:["An technische Dienstleister — Hosting und Serverinfrastruktur, E-Mail-Versand, gegebenenfalls Zahlungsdienstleister und IT-Support. Diese Empfänger handeln als Auftragsverarbeiter auf Grundlage eines Vertrags nach Art. 28 DSGVO.","An den Veranstalter — im für Reservierung, Ticket und Einlass erforderlichen Umfang.","An Steuerberater und Berater — im für die Erfüllung gesetzlicher Pflichten erforderlichen Umfang.","An Behörden — nur soweit gesetzlich vorgeschrieben.","Wir verkaufen keine personenbezogenen Daten und geben sie nicht für eigene Marketingzwecke Dritter weiter."]},{heading:"6. Übermittlung in Drittländer",paragraphs:["Wir verarbeiten die Daten innerhalb der Europäischen Union und des Europäischen Wirtschaftsraums.","Käme es bei einem Dienst (etwa bei der Anmeldung über ein Google- oder Facebook-Konto) zu einer Übermittlung außerhalb des EWR, erfolgt sie auf Grundlage eines Angemessenheitsbeschlusses der Kommission oder der von der Europäischen Kommission genehmigten Standardvertragsklauseln."]},{heading:"7. Ihre Rechte",paragraphs:["Sie haben das Recht auf Auskunft über Ihre Daten und auf eine Kopie der verarbeiteten Daten.","Sie haben das Recht auf Berichtigung unrichtiger und Vervollständigung unvollständiger Daten.","Sie haben das Recht auf Löschung, sofern die Daten nicht mehr benötigt werden und keine gesetzliche Aufbewahrungspflicht entgegensteht.","Sie haben das Recht auf Einschränkung der Verarbeitung und auf Übertragbarkeit der von Ihnen bereitgestellten Daten.","Sie haben das Recht, der auf berechtigtem Interesse beruhenden Verarbeitung zu widersprechen, und das Recht, eine Einwilligung jederzeit zu widerrufen, wo sie Rechtsgrundlage ist.","Anfragen senden Sie an {email}. Wir antworten spätestens innerhalb eines Monats nach Eingang.","Sie haben das Recht auf Beschwerde bei der Aufsichtsbehörde: Úrad na ochranu osobných údajov Slovenskej republiky, Hraničná 12, 820 07 Bratislava 27, Slowakei, www.dataprotection.gov.sk."]},{heading:"8. Automatisierte Entscheidungsfindung",paragraphs:["Wir führen keine automatisierte Entscheidungsfindung und kein Profiling durch, die Ihnen gegenüber rechtliche Wirkung entfalten oder Sie in ähnlicher Weise erheblich beeinträchtigen würden."]},{heading:"9. Cookies und lokaler Speicher",paragraphs:["Das Portal verwendet notwendige Cookies und den lokalen Speicher des Browsers für Anmeldung, Sicherheit und das Merken der gewählten Sprache. Ohne sie würde das Portal nicht funktionieren, daher ist hierfür keine Einwilligung erforderlich.","Sollten wir Analyse- oder Marketing-Cookies einsetzen, holen wir vorab Ihre Einwilligung ein; diese ist jederzeit widerrufbar.","Gespeicherte Cookies können Sie jederzeit in den Einstellungen Ihres Browsers löschen; einzelne Funktionen des Portals funktionieren dann möglicherweise nicht mehr."]},{heading:"10. Änderungen dieses Dokuments",paragraphs:["Die aktuelle Fassung ist stets auf dieser Seite verfügbar. Über wesentliche Änderungen informieren wir registrierte Nutzer per E-Mail oder durch einen Hinweis auf dem Portal.","Diese Fassung gilt ab {effectiveFrom} (Version {version}). Maßgeblich ist der slowakische Wortlaut; andere Sprachfassungen sind eine informative Übersetzung."]}]}},N={terms:{title:"Terms and Conditions",perex:"These terms and conditions govern the rights and obligations arising from the use of the {site} portal. This version is effective from {effectiveFrom} (version {version}). The Slovak wording prevails.",sections:[{heading:"Art. 1 — Operator",paragraphs:["1.1 The {site} portal (the “Portal”) is operated by {name}, registered office {address}, Company ID: {ico}, {dic}, {registration} (the “Operator”).","1.2 Contact details: e-mail {email}, phone {phone}.","1.3 The supervisory authority is the Slovak Trade Inspection (Slovenská obchodná inšpekcia) — {soi}."]},{heading:"Art. 2 — Definitions",paragraphs:["2.1 Portal — the web application available at {site} publishing information about cultural, social, sporting and other events, and related services.","2.2 User — a natural or legal person using the Portal, including without registration.","2.3 Registered User — a User with an account on the Portal.","2.4 Organiser — a Registered User who publishes events on the Portal or offers tickets through it.","2.5 Visitor — a User who reserves or buys a ticket through the Portal, or signs up for an event.","2.6 Content — texts, photographs, posters, links and other data uploaded to the Portal by a User.","2.7 Agreement — the contract for the provision of the Portal’s services between the Operator and a Registered User, the content of which is set out in these terms."]},{heading:"Art. 3 — Registration and user account",paragraphs:["3.1 Registration is free of charge and voluntary. Published events can be browsed without it.","3.2 An account may be created by a person over 16 years of age. For a younger person, only their legal representative may act.","3.3 The User completes registration by filling in the form and ticking their agreement with these terms. The Agreement is concluded upon verification of the e-mail address, or upon the first sign-in via a Google or Facebook account.","3.4 The User provides truthful and current data and is responsible for keeping their account credentials confidential. Any suspected misuse of the account must be reported without delay to {email}.","3.5 The account is non-transferable. The User is responsible for actions carried out through their account.","3.6 A User registering as an Organiser on behalf of a legal entity declares that they are authorised to act for it."]},{heading:"Art. 4 — Content published by Users",paragraphs:["4.1 The User who uploaded the Content is responsible for its accuracy, lawfulness and timeliness. The Operator does not create the Content and does not warrant its completeness or truthfulness.","4.2 By uploading Content, the User grants the Operator a free, non-exclusive and territorially unlimited licence to display, reproduce, resize and distribute it to the extent needed to operate and promote the Portal, including previews in search engines and on social networks, for as long as the Content is published on the Portal.","4.3 The User declares that they are entitled to grant such a licence and that the Content does not infringe the rights of third parties, in particular copyright, personality rights and trade mark rights.","4.4 Content contrary to the laws of the Slovak Republic or to good morals is prohibited, in particular content that is hateful, defamatory, misleading, fundamentally unrelated to events, promoting violence, or unsuitable for minors.","4.5 The Operator may refuse to publish Content that breaches these terms, change its categorisation, or remove it. The Operator informs the User of any removal; the User may object at {email}.","4.6 The Operator is not obliged to review Content in advance. It responds without undue delay to notices of unlawful Content sent to {email}."]},{heading:"Art. 5 — Tickets and payments",paragraphs:["5.1 Where the Portal allows tickets to be reserved or sold, the Operator acts as an intermediary in the name and on behalf of the Organiser. The contract for attending the event is concluded between the Visitor and the Organiser, not with the Operator.","5.2 Ticket prices are stated including value added tax. Any service or transaction fees are shown before the order is bindingly submitted; the total amount payable is displayed to the Visitor before the order is confirmed.","5.3 The ticket is delivered electronically to the e-mail address given in the order and is valid together with a unique code checked at the entrance. The Visitor is responsible for protecting the ticket against copying; if the same code is used repeatedly, the first admission prevails.","5.4 The Organiser alone is responsible for holding the event, its content, course, change of date or venue, and cancellation. Refunds for cancelled or rescheduled events are handled by the Organiser.","5.5 A free reservation or sign-up does not create a right of entry beyond the capacity announced by the Organiser."]},{heading:"Art. 6 — Withdrawal and complaints",paragraphs:["6.1 A Registered User who is a consumer may withdraw from the Agreement on the use of the Portal at any time by deleting their account, without giving a reason. The service is free of charge, so withdrawal involves no costs.","6.2 The consumer’s 14-day right of withdrawal does not apply to event tickets. This is the provision of a service related to leisure activities where the provider undertakes to perform at an agreed time — the exception under Section 19 of Act No. 108/2024 Coll. on consumer protection.","6.3 Complaints about the Portal’s services may be submitted by e-mail to {email}. The Operator confirms receipt, settles the complaint no later than 30 days from its submission and issues a written record of the outcome.","6.4 Complaints about the event itself (its course, quality or cancellation) are to be raised with the Organiser, who is the contracting party."]},{heading:"Art. 7 — Operation of the Portal and liability",paragraphs:["7.1 The Operator makes reasonable efforts to keep the Portal continuously available but does not guarantee it. The Portal may be unavailable for the time necessary due to maintenance, updates or third-party outages.","7.2 The Operator may change the scope and form of the Portal’s features. Should it decide to discontinue operation, it will notify Registered Users at least 30 days in advance.","7.3 The Operator is not liable for damage caused by unavailability of the Portal, loss of uploaded Content or acts of third parties, unless caused intentionally or by gross negligence. This does not affect liability for damage to health or other liability that cannot be excluded.","7.4 Users must not burden the Portal with automated data retrieval beyond ordinary use, circumvent security features, or interfere with its technical implementation."]},{heading:"Art. 8 — Duration and termination",paragraphs:["8.1 The Agreement is concluded for an indefinite period.","8.2 The User may delete the account at any time in the account settings or by request to {email}.","8.3 The Operator may restrict or delete an account if the User seriously or repeatedly breaches these terms, or if the account is manifestly being misused. The Operator informs the User by e-mail, stating the reason.","8.4 Deleting the account terminates the Agreement. Information about events that have already taken place may remain in the Portal’s archive; personal data is further processed only as described in the privacy notice."]},{heading:"Art. 9 — Personal data",paragraphs:["9.1 The Operator processes personal data to the extent and in the manner described in the Privacy Notice, which forms an informational part of these terms.","9.2 Processing of data necessary to maintain the account and provide the Portal’s services is based on performance of this Agreement, not on consent — it therefore cannot be withdrawn separately while the account exists."]},{heading:"Art. 10 — Alternative dispute resolution",paragraphs:["10.1 A consumer dissatisfied with the way a complaint was handled, or who believes the Operator has infringed their rights, may request redress at {email}.","10.2 If the Operator rejects the request or fails to reply within 30 days, the consumer has the right to file a proposal to initiate alternative dispute resolution under Act No. 391/2015 Coll. on alternative resolution of consumer disputes.","10.3 The competent body is the Slovak Trade Inspection (Ústredný inšpektorát SOI, Bajkalská 21/A, 827 99 Bratislava, www.soi.sk) or another authorised entity listed in the register of alternative dispute resolution entities maintained by the Ministry of Economy of the Slovak Republic. The consumer may choose which one to approach.","10.4 Alternative dispute resolution is free of charge for the consumer or subject to a fee of no more than EUR 5. The right to bring the matter before a court is not affected."]},{heading:"Art. 11 — Final provisions",paragraphs:["11.1 Legal relationships not governed by these terms are subject to the law of the Slovak Republic, in particular the Civil Code, Act No. 108/2024 Coll. on consumer protection and Act No. 22/2004 Coll. on electronic commerce.","11.2 The Operator may amend these terms, in particular following changes in legislation or in the scope of services. Registered Users are notified of any amendment by e-mail or by a notice on the Portal at least 15 days before the new version takes effect.","11.3 A User who does not agree with an amendment may delete their account before it takes effect. Continuing to use the Portal after that date constitutes acceptance.","11.4 Should any provision of these terms become invalid or ineffective, the remaining provisions remain in force.","11.5 These terms are drawn up in the Slovak language; versions in other languages are an informative translation and, in the event of a discrepancy, the Slovak wording prevails.","11.6 This version takes effect on {effectiveFrom} and supersedes all previous versions (version {version})."]}]},privacy:{title:"Privacy Notice",perex:"This notice explains what personal data the {site} portal processes about you, for what purpose, for how long, and what rights you have. We act in accordance with Regulation (EU) 2016/679 (GDPR) and Act No. 18/2018 Coll. on personal data protection. This version is effective from {effectiveFrom} (version {version}).",sections:[{heading:"1. Who processes the data",paragraphs:["The controller within the meaning of the GDPR is {name}, registered office {address}, Company ID: {ico}, {registration}.","For data protection matters, contact us at {email} or in writing at the registered office address."]},{heading:"2. What data we process",paragraphs:["Registration data — e-mail address, name or company name, password (stored solely as an unreadable hash) and the registration method (e-mail, Google, Facebook).","Consent record — the date and version of the terms and conditions you agreed to during registration.","Organiser profile and billing data — name, contact and billing details, if you provide them.","Content you publish — events, venues, photographs, posters and texts, including any contact details you state in them.","Communication — the content of messages sent through the Portal and of e-mail correspondence with us.","Ticket data — tickets ordered, their status and the record of admission to the event.","Technical data — IP address, browser type and language, date and time of access, sign-in records and application error logs."]},{heading:"3. Purposes and legal bases",paragraphs:["Maintaining the user account and providing the Portal’s features — performance of a contract under Art. 6(1)(b) GDPR. Providing this data is necessary; without it no account can be created.","Publishing the content you upload, including its display in search engines — performance of a contract under Art. 6(1)(b) GDPR.","Intermediating tickets, delivering them and checking them at the entrance — performance of a contract under Art. 6(1)(b) GDPR; data needed for admission is passed to the event Organiser.","Verifying the e-mail address, securing accounts and protecting against misuse and spam — legitimate interest under Art. 6(1)(f) GDPR.","Demonstrating the consent given to the terms and conditions — legal obligation under Art. 6(1)(c) in conjunction with Art. 7(1) GDPR.","Bookkeeping and tax compliance for paid services — legal obligation under Art. 6(1)(c) GDPR.","Sending newsletters and event alerts where you request them — consent under Art. 6(1)(a) GDPR, which you may withdraw at any time without affecting the lawfulness of processing before withdrawal.","Establishing or defending legal claims — legitimate interest under Art. 6(1)(f) GDPR."]},{heading:"4. How long we keep the data",paragraphs:["Account data — for as long as the account exists and then for up to 1 year after deletion, for any claims arising from use of the Portal.","Unverified registration — at most until the verification link expires (48 hours), after which it is deleted automatically.","Consent record — for the lifetime of the account and 1 year after its deletion, together with the account data.","Published event content — may remain in the Portal’s archive even after the account is deleted, as a rule without contact details of natural persons.","Ticket data and accounting records — 10 years, where required by tax and accounting legislation.","Technical logs — as a rule 12 months."]},{heading:"5. Who we share the data with",paragraphs:["Technical service providers — hosting and server infrastructure, e-mail delivery, and where applicable a payment gateway and IT support. These recipients act as processors under a contract pursuant to Art. 28 GDPR.","The event Organiser — to the extent needed for the reservation, the ticket and admission to the event.","Accountants and advisers — to the extent needed to meet statutory obligations.","Public authorities — only where required by law.","We do not sell personal data and do not provide it to third parties for their own marketing purposes."]},{heading:"6. Transfers to third countries",paragraphs:["We process data within the European Union and the European Economic Area.","Should a transfer outside the EEA occur with any service (for example when signing in with a Google or Facebook account), it takes place on the basis of a Commission adequacy decision or standard contractual clauses approved by the European Commission."]},{heading:"7. Your rights",paragraphs:["You have the right of access to your data and to a copy of the data processed.","You have the right to have inaccurate data corrected and incomplete data completed.","You have the right to erasure where the data is no longer needed and no statutory retention obligation applies.","You have the right to restriction of processing and the right to portability of the data you provided to us.","You have the right to object to processing based on legitimate interest and to withdraw consent at any time where consent is the legal basis.","Send requests to {email}. We will respond within one month of receiving the request at the latest.","You have the right to lodge a complaint with the supervisory authority: Úrad na ochranu osobných údajov Slovenskej republiky, Hraničná 12, 820 07 Bratislava 27, Slovakia, www.dataprotection.gov.sk."]},{heading:"8. Automated decision-making",paragraphs:["We do not carry out automated decision-making or profiling that would produce legal effects concerning you or similarly significantly affect you."]},{heading:"9. Cookies and local storage",paragraphs:["The Portal uses strictly necessary cookies and browser local storage for sign-in, security and remembering the chosen language. The Portal would not work without them, so no consent is required.","Should we deploy analytics or marketing cookies, we will ask for your consent in advance and it will be withdrawable at any time.","You can delete stored cookies at any time in your browser settings; some features of the Portal may then stop working."]},{heading:"10. Changes to this notice",paragraphs:["The current version is always available on this page. We inform registered users of material changes by e-mail or by a notice on the Portal.","This version is effective from {effectiveFrom} (version {version}). The Slovak wording prevails; other language versions are an informative translation."]}]}},E="2026-08-14",B="14. 8. 2026",G={site:"vyveska.sk",name:"[DOPLNIŤ: obchodné meno prevádzkovateľa]",address:"[DOPLNIŤ: sídlo — ulica, PSČ, obec]",ico:"[DOPLNIŤ: IČO]",dic:'[DOPLNIŤ: DIČ / IČ DPH alebo „neplatiteľ DPH"]',registration:"[DOPLNIŤ: zápis v OR SR, oddiel a vložka / číslo živnostenského registra]",email:"[DOPLNIŤ: kontaktný e-mail]",phone:"[DOPLNIŤ: telefón]",soi:"[DOPLNIŤ: Inšpektorát SOI pre … kraj, adresa]"},m={sk:O,cs:V,de:T,en:N},I={...G,version:E,effectiveFrom:B};function l(o){return o.replace(/\{(\w+)\}/g,(n,e)=>I[e]??n)}function U(o,n=z()){const e=(m[n]??m.sk)[o];return{title:l(e.title),perex:l(e.perex),sections:e.sections.map(d=>({heading:l(d.heading),paragraphs:d.paragraphs.map(l)}))}}const Z={class:"legal-shell"},F={class:"legal-head"},x={class:"m-0 text-2xl md:text-3xl"},K={class:"m-0 text-sm text-slate-600"},C={class:"legal-heading"},M={class:"legal-foot"},W=f({__name:"LegalPage",props:{kind:{}},setup(o){const n=o,{t:e,locale:d}=A(),r=h(()=>U(n.kind,d.value)),p=h(()=>n.kind==="terms"?{to:"/ochrana-osobnych-udajov",label:e("legal.privacy")}:{to:"/obchodne-podmienky",label:e("legal.terms")});return j(h(()=>({title:`${r.value.title} | Event`,meta:[{name:"description",content:r.value.perex},{name:"robots",content:"noindex, follow"}]}))),(L,_)=>{const g=D("RouterLink");return s(),i("article",Z,[a("header",F,[a("h1",x,t(r.value.title),1),a("p",K,t(r.value.perex),1)]),(s(!0),i(v,null,c(r.value.sections,u=>(s(),i("section",{key:u.heading,class:"legal-section"},[a("h2",C,t(u.heading),1),(s(!0),i(v,null,c(u.paragraphs,(k,b)=>(s(),i("p",{key:b,class:"legal-paragraph"},t(k),1))),128))]))),128)),a("footer",M,[a("span",null,t(y(e)("legal.alsoSee")),1),P(g,{to:p.value.to},{default:w(()=>[R(t(p.value.label),1)]),_:1},8,["to"])])])}}}),q=S(W,[["__scopeId","data-v-f67d5068"]]);export{q as default};
